import React,{useEffect,useState} from 'react'
import {recordingApi,type RecordingConfig} from '../../../../shared/client/recording-client.ts'
import s from './ManagedCapabilities.module.css'
export function RecordingSettings({disabled=false}:{disabled?:boolean}){const [config,setConfig]=useState<RecordingConfig>(),[role,setRole]=useState(''),[busy,setBusy]=useState(false),[notice,setNotice]=useState('');useEffect(()=>{void recordingApi<RecordingConfig>('config').then(c=>{setConfig(c);setRole(c.roleId)}).catch(e=>setNotice(e.message))},[]);return <div className={s.row} style={{display:'block'}}><strong>录音与保存</strong><p className={s.muted}>使用默认麦克风。宠物按钮与对话指令共用一条录音；录音过程中分批保存。</p><label>录音归属岗位<select aria-label="录音归属岗位" disabled={disabled||busy} value={role} onChange={e=>{setRole(e.target.value);setNotice('')}} style={{display:'block',width:'100%',margin:'10px 0',padding:10,borderRadius:10}}><option value="">请选择已绑定的岗位</option>{role&&!config?.roles.some(r=>r.id===role)&&<option value={role} disabled>原岗位已不可用，请重新选择</option>}{config?.roles.map(r=><option key={r.id} value={r.id}>{r.name}</option>)}</select></label>{config&&!config.roles.length&&<p>请先在岗位编辑中添加“录音与保存”能力。</p>}<p className={s.muted}>新录音及新会话归属于此岗位。修改只影响下一次录音。</p><button className={s.button} disabled={disabled||busy||!role} onClick={()=>{setBusy(true);void recordingApi<RecordingConfig>('config',{roleId:role}).then(c=>{setConfig(c);setNotice('已保存，下次录音生效')}).catch(e=>setNotice(e.message)).finally(()=>setBusy(false))}}>保存</button>{notice&&<p role="status">{notice}</p>}</div>}
