import React, {useSyncExternalStore} from 'react'
import {recordingClient,recordingTime} from './recording-client.ts'
export function RecordingIcon({kind}:{kind:string}){return <svg width="17" height="17" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">{kind==='start'?<><rect x="9" y="2" width="6" height="12" rx="3"/><path d="M5 10v2a7 7 0 0 0 14 0v-2M12 19v3M8 22h8"/></>:kind==='pause'?<><path d="M8 5v14M16 5v14"/></>:kind==='resume'?<path d="m8 4 12 8-12 8Z"/>:kind==='finish'?<path d="m4 12 5 5L20 6"/>:<path d="m6 6 12 12M6 18 18 6"/>}</svg>}
export function RecordingControls({tone}:{tone?:'pet'}){const c=recordingClient(),s=useSyncExternalStore(c.subscribe,c.getSnapshot),row=s.rows.find(r=>r.id===s.activeId);const actions=row?[[row.status==='paused'?'resume':'pause',row.status==='paused'?'继续录音':'暂停录音'],['finish','完成录音'],['cancel','取消录音']]:[['start','开始录音']];return <div style={{display:'flex',gap:6,alignItems:'center'}}>{row&&<small style={{fontSize:12,fontVariantNumeric:'tabular-nums',color:row.status==='paused'?'inherit':tone==='pet'?'#ffadbd':'#b43e50'}}>{recordingTime(s.elapsed)}</small>}{actions.map(([action,label])=><button key={action} type="button" title={label} aria-label={label} disabled={s.busy} onClick={()=>{if(action==='cancel'&&!window.confirm('取消并丢弃这次录音？'))return;void c.run(action!)}} style={{width:30,height:30,padding:5,borderRadius:10,border:tone==='pet'?'1px solid #6782ff':'1px solid var(--border-color, #aab4d0)',background:tone==='pet'?'linear-gradient(135deg,#506fff,#344dde)':'var(--surface-color, #edf0f8)',color:tone==='pet'?'#fff':'inherit',display:'grid',placeItems:'center',cursor:'pointer'}}><RecordingIcon kind={action!}/></button>)}</div>}
