import React,{useEffect,useRef,useState,useSyncExternalStore} from 'react'
import {PillCheckbox} from '../../../../shared/client/PillCheckbox.tsx'
import {documentsClient,documentDesktop,documentApi} from '../../../../shared/client/documents-client.ts'
import {MessageTime} from './MessageTime.tsx'
import s from './DocumentAssistant.module.css'
export function DocumentAssistant({roleId,loadModels}:{roleId:string;loadModels:()=>Promise<{id:string;name:string}[]>}){
 const client=documentsClient(),state=useSyncExternalStore(client.subscribe,client.getSnapshot),mount=useRef<HTMLDivElement>(null),input=useRef<HTMLInputElement>(null),[side,setSide]=useState(true),[sideWidth,setSideWidth]=useState(380),[contentTab,setContentTab]=useState<'text'|'selection'|'outline'>('text')
 const [models,setModels]=useState<{id:string;name:string}[]>([]),[sending,setSending]=useState(false),[history,setHistory]=useState(false),[historyQuery,setHistoryQuery]=useState('')
 const draftKey=state.active?.roleId===roleId?state.active.id:'role:'+roleId,{model,question,scope,chapter,mode,useKnowledge}=client.draft(draftKey)
 const setModel=(model:string)=>client.updateDraft(draftKey,{model}),setQuestion=(question:string)=>client.updateDraft(draftKey,{question}),setScope=(scope:string)=>client.updateDraft(draftKey,{scope}),setChapter=(chapter:number)=>client.updateDraft(draftKey,{chapter}),setMode=(mode:'ask'|'revise')=>client.updateDraft(draftKey,{mode}),setUseKnowledge=(useKnowledge:boolean)=>client.updateDraft(draftKey,{useKnowledge})
 const [knowledge,setKnowledge]=useState<{configured:boolean;verified:boolean;message:string;label:string}>({configured:false,verified:false,message:'接口已预留，暂未接入服务。',label:'外部资料库'})
 useEffect(()=>{void documentApi<typeof knowledge>('knowledge').then(setKnowledge).catch(client.fail)},[])
 const generating=state.active?.messages.some(m=>m.status==='running'),chapters=state.context?.paragraphs.map((p,index)=>({...p,index})).filter(p=>/^Heading\d$/i.test(p.styleId||''))??[]
 useEffect(()=>{void loadModels().then(setModels).catch(client.fail)},[])
 async function ask(value=question,preserveDraft=false){if(!value.trim()||generating||sending)return;setSending(true);try{await client.ask({question:value,model,mode,useKnowledge,scope:scope==='auto'?state.context?.selection?'selection':'document':scope,chapter});if(!preserveDraft)setQuestion('')}finally{setSending(false)}}
 useEffect(()=>{void client.refresh();return client.mount(mount.current!)},[])
 useEffect(()=>{void client.activateRole(roleId).catch(client.fail)},[roleId])
 const run=(fn:()=>Promise<unknown>)=>{void fn().catch(client.fail)}
 async function file(value?:File){if(value){const path=documentDesktop()?.getPathForFile?.(value);if(path&&documentDesktop()?.openDocument)await client.openNative(roleId,path);else await client.importBytes(value.name,await value.arrayBuffer(),roleId)}}
 return <section className={s.root} aria-label="智能文档工作区" onDragOver={e=>{if(e.dataTransfer.types.includes('Files'))e.preventDefault()}} onDrop={e=>{e.preventDefault();run(()=>file(e.dataTransfer.files[0]))}}>
  <header className={s.toolbar}><div className={s.identity}><strong>{state.active?.title||'智能文档助手'}</strong><small>{state.busy?'正在打开…':state.saving?'正在暂存…':state.active?state.dirty?'有未保存修改 · '+(state.draftSaved?'工作副本已暂存':'正在暂存'):'工作副本已就绪':'打开 Word，编辑并理解文档'}</small></div>
   <input ref={input} type="file" accept=".docx" hidden onChange={e=>{run(()=>file(e.target.files?.[0]));e.target.value=''}}/>
   <button disabled={state.busy} onClick={()=>documentDesktop()?.openDocument?run(()=>client.openNative(roleId)):input.current?.click()}>打开 Word</button>
   <button disabled={!state.active||state.busy} onClick={()=>run(()=>client.save(false))}>{state.active&&!client.hasNative(state.active.id)?'保存副本':'保存'}</button>
   <button disabled={!state.active||state.busy} onClick={()=>run(()=>client.save(true))}>另存为</button>
   <button aria-expanded={history} aria-controls="document-history" onClick={()=>{setHistory(!history);if(!history)void client.refresh()}}>历史记录</button>
   <button aria-expanded={side} onClick={()=>setSide(!side)}>{side?'收起助手':'展开助手'}</button>
  </header>
  {history&&<section id="document-history" className={s.history} aria-label="文档历史记录">
   <header className={s.panelHeader}><strong>历史记录</strong><input autoFocus type="search" aria-label="搜索文档历史" placeholder="搜索文档或问答…" value={historyQuery} onChange={e=>setHistoryQuery(e.target.value)}/><button aria-label="关闭历史记录" onClick={()=>setHistory(false)}>×</button></header>
   <div className={s.historyList}>{state.rows.filter(row=>row.roleId===roleId&&(row.conversationId||row.id)===state.conversationId&&!row.removedAt&&(row.title+' '+row.messages.map(m=>m.text).join(' ')).toLocaleLowerCase().includes(historyQuery.toLocaleLowerCase())).map(row=><div className={s.historyItem} key={row.id}><button disabled={state.busy||sending} aria-current={row.id===state.active?.id?'true':undefined} onClick={()=>run(async()=>{await client.open(row.id);setHistory(false)})}><strong>{row.title}</strong><small>{new Date(row.updatedAt).toLocaleString()} · {row.messages.filter(m=>m.role==='user').length} 个问题{row.id===state.active?.id?' · 当前文档':''}</small>{row.messages.length>0&&<span>{row.messages.at(-1)?.text}</span>}</button><button className={s.removeHistory} aria-label={'移除历史记录：'+row.title} title="移除记录（不删除原始 Word 文件）" disabled={state.busy||sending} onClick={()=>run(()=>client.command(row.id,'remove'))}><svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8" aria-hidden="true"><path d="M3 6h18M9 6V3h6v3M5 6l1 15h12l1-15M10 10v7M14 10v7"/></svg></button></div>)}{!state.rows.some(row=>row.roleId===roleId&&(row.conversationId||row.id)===state.conversationId&&!row.removedAt&&(row.title+' '+row.messages.map(m=>m.text).join(' ')).toLocaleLowerCase().includes(historyQuery.toLocaleLowerCase()))&&<p className={s.hint}>{historyQuery?'没有匹配的历史记录':'当前对话打开过的文档及问答会保存在这里。'}</p>}</div>
  </section>}
  {state.error&&<div className={s.error} role="alert">{state.error}<button onClick={client.clearError} aria-label="关闭提示">×</button></div>}
  <div className={s.layout} data-sidebar={side} style={{'--doc-side-width':sideWidth+'px'} as React.CSSProperties}><div className={s.editor}><div className={s.frame} data-empty={!state.active} ref={mount}/>{!state.active&&<div className={s.empty}><span className={s.emptyIcon} aria-hidden="true">W</span><strong>从一份 Word 开始</strong><p>点击“打开 Word”或将 DOCX 拖到这里。工作副本在本机暂存。</p><button className={s.openAction} disabled={state.busy} onClick={()=>documentDesktop()?.openDocument?run(()=>client.openNative(roleId)):input.current?.click()}>打开 Word 文档</button>{state.rows.some(row=>row.roleId===roleId&&(row.conversationId||row.id)===state.conversationId)&&<small>最近打开</small>}{state.rows.filter(row=>row.roleId===roleId&&(row.conversationId||row.id)===state.conversationId).slice(0,6).map(row=><button key={row.id} onClick={()=>run(()=>client.open(row.id))}>{row.title}<small>{new Date(row.updatedAt).toLocaleString()}</small></button>)}</div>}</div>
   {side&&<><div className={s.resize} role="separator" aria-label="调整文档助手宽度" aria-orientation="vertical" aria-valuenow={sideWidth} aria-valuemin={290} aria-valuemax={600} tabIndex={0} onKeyDown={e=>{if(e.key==='ArrowLeft'||e.key==='ArrowRight'){e.preventDefault();setSideWidth(w=>Math.max(290,Math.min(600,w+(e.key==='ArrowLeft'?20:-20))))}}} onPointerDown={e=>{e.currentTarget.setPointerCapture(e.pointerId)}} onPointerMove={e=>{if(e.currentTarget.hasPointerCapture(e.pointerId)){const rect=e.currentTarget.parentElement!.getBoundingClientRect();setSideWidth(Math.max(290,Math.min(600,rect.right-e.clientX)))}}} onPointerUp={e=>e.currentTarget.releasePointerCapture(e.pointerId)}/><aside className={s.side}>
    <section className={s.preview} aria-label="文档内容">
     <header className={s.panelHeader}><strong>文档内容</strong><div className={s.tabs} role="tablist" aria-label="文档内容视图">{([{id:'text',label:'原文'},{id:'selection',label:'选区'},{id:'outline',label:'大纲'}] as const).map(tab=><button key={tab.id} id={'document-tab-'+tab.id} role="tab" aria-selected={contentTab===tab.id} aria-controls="document-content-panel" tabIndex={contentTab===tab.id?0:-1} onKeyDown={e=>{const tabs=['text','selection','outline'] as const;const index=tabs.indexOf(tab.id);const next=e.key==='ArrowRight'?tabs[(index+1)%3]:e.key==='ArrowLeft'?tabs[(index+2)%3]:e.key==='Home'?'text':e.key==='End'?'outline':null;if(next){e.preventDefault();setContentTab(next);document.getElementById('document-tab-'+next)?.focus()}}} onClick={()=>setContentTab(tab.id)}>{tab.label}</button>)}</div></header>
     <div className={s.context} id="document-content-panel" role="tabpanel" aria-labelledby={'document-tab-'+contentTab} tabIndex={0}>
      {contentTab==='text'&&(state.context?.paragraphs.length?state.context.paragraphs.map((p,i)=><p key={p.paraId||i} className={/^Heading\d$/i.test(p.styleId||'')?s.heading:undefined}>{p.text}</p>):<p className={s.hint}>打开 Word 后，这里显示可用于问答的正文。</p>)}
      {contentTab==='selection'&&<p className={!state.context?.selection?s.hint:undefined}>{state.context?.selection||'在左侧文档中选择文字，这里会显示选中内容。'}</p>}
      {contentTab==='outline'&&(state.context?.outline.length?state.context.outline.map((item,i)=><button key={i} style={{paddingLeft:Math.min(4,item.level)*10+4}} onClick={()=>run(()=>client.rpc('find',{text:item.text}))}>{item.text}</button>):<p className={s.hint}>当前文档暂无可识别的标题大纲。</p>)}
     </div>
    </section>
    <section className={s.chat} aria-label="文档问答">
    <header className={s.panelHeader}><strong>文档问答</strong><div className={s.tabs}><button aria-pressed={mode==='ask'} onClick={()=>setMode('ask')}>理解文档</button><button aria-pressed={mode==='revise'} onClick={()=>setMode('revise')}>AI 修改</button></div></header>
    <div className={s.messages} aria-live="polite">{state.active?.messages.map((message,messageIndex)=><article key={message.id} data-role={message.role}><small>{message.role==='user'?'你':'文档助手'} · {message.scope}</small><p>{message.text||(message.status==='running'?'正在理解文档…':'')}</p>{message.role==='assistant'&&[...new Set([...message.text.matchAll(/\[P(\d+)\]/g)].map(m=>Number(m[1])-1))].filter(i=>message.sources?.some(p=>p.id==='P'+(i+1))).map(i=><button key={i} onClick={()=>run(()=>client.rpc('find',{text:message.sources!.find(p=>p.id==='P'+(i+1))!.text,paraId:message.sources!.find(p=>p.id==='P'+(i+1))!.paraId}))}>定位 P{i+1}</button>)}{message.knowledge?.map(source=><details key={source.id}><summary>[{source.id}] {source.title}</summary><p>{source.text}</p>{source.url&&<a href={source.url} target="_blank" rel="noreferrer">查看来源</a>}</details>)}{message.proposal&&<div className={s.proposal}><strong>修改建议</strong><del>{message.proposal.before}</del><ins>{message.proposal.after}</ins><button disabled={state.busy||message.proposal.status==='adopted'} onClick={()=>run(()=>client.adopt(message.proposal!.id))}>{message.proposal.status==='adopted'?'已采用':'采用修改'}</button><button onClick={()=>run(()=>client.rpc('find',{text:message.proposal!.before,paraId:message.proposal!.paraId}))}>定位原文</button></div>}{message.status!=='running'&&<footer className={s.messageFooter}><MessageTime value={message.createdAt}/>{(message.role==='user'||state.active!.messages.slice(0,messageIndex).some(m=>m.role==='user'))&&<button type="button" aria-label="重新生成" title="使用当前文档、范围和模型重新生成此问题的回答；保留已有记录" disabled={generating||sending||state.busy} onClick={()=>run(()=>ask(message.role==='user'?message.text:state.active!.messages.slice(0,messageIndex).filter(m=>m.role==='user').at(-1)!.text,true))}><svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8" aria-hidden="true"><path d="M20 7v5h-5M4 17v-5h5"/><path d="M6.1 7a7 7 0 0 1 11.6-1L20 9M4 15l2.3 3A7 7 0 0 0 17.9 17"/></svg></button>}</footer>}</article>)}{!state.active?.messages.length&&<div className={s.suggestions}>{['概括文档的主要内容','解释选区的业务含义','列出需要进一步确认的问题'].map(value=><button disabled={!state.active||sending} key={value} onClick={()=>run(()=>ask(value))}>{value}</button>)}</div>}</div>
    <form className={s.composer} onSubmit={e=>{e.preventDefault();run(()=>ask())}}><div className={s.options}><select aria-label="问答范围" value={scope} onChange={e=>setScope(e.target.value)}><option value="auto">{state.context?.selection?'当前选区':'全文正文'}</option><option value="document">全文正文</option><option value="selection" disabled={!state.context?.selection}>当前选区</option><option value="chapter" disabled={!chapters.length}>指定章节</option></select><select aria-label="文档问答模型" value={model} onChange={e=>setModel(e.target.value)}><option value="">工作台默认模型</option>{models.map(m=><option key={m.id} value={m.id}>{m.name}</option>)}</select></div>{scope==='chapter'&&<select aria-label="选择章节" value={chapter} onChange={e=>setChapter(Number(e.target.value))}><option value={-1}>选择章节</option>{chapters.map(p=><option key={p.index} value={p.index}>{p.text}</option>)}</select>}<textarea rows={3} aria-label="向文档助手提问" placeholder={mode==='revise'?'描述要怎样修改；一次改写一处段落内文字…':'询问文档、解释选区…'} value={question} onChange={e=>setQuestion(e.target.value)} onKeyDown={e=>{if(e.key==='Enter'&&(e.ctrlKey||e.metaKey)){e.preventDefault();run(()=>ask())}}}/><div className={s.options}><button type="button" disabled={!state.active} onClick={()=>run(()=>client.undoAI())}>撤销 AI 修改</button>{generating?<button type="button" onClick={()=>run(()=>client.stop())}>停止生成</button>:<button type="submit" disabled={!state.active||sending||!question.trim()}>{sending?'提交中…':mode==='revise'?'生成修改建议':'发送'}</button>}</div></form><p className={s.hint} title={knowledge.message}>问答使用当前模型 API · Ctrl + Enter 发送</p>{knowledge.configured&&<label className={s.hint}><PillCheckbox checked={useKnowledge} onChange={e=>setUseKnowledge(e.target.checked)}/>结合 {knowledge.label}{knowledge.verified?'':'（连接待验证）'}</label>}</section></aside></>}
  </div>
 </section>
}
