import React,{type ReactNode} from 'react'
import s from '../../packages/dsh-client-ui-plain-chat/src/client/ManagedCapabilities.module.css'
import glyph from '../../packages/dsh-client-ui-plain-chat/src/client/Capabilities.module.css'
export function ManagementIcon({kind}:{kind:'pin'|'remove'|'file'}){return <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.7" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">{kind==='pin'?<><path d="M16 3 21 8l-4 1-3 5v3l-7-7h3l5-3z"/><path d="m3 21 7-7"/></>:kind==='remove'?<><path d="M3 6h18M9 6V3h6v3M5 6l1 15h12l1-15M10 10v7M14 10v7"/></>:<><path d="M6 3h8l4 4v14H6zM14 3v5h4M9 12h6M9 16h6"/></>}</svg>}
export function ManagementRow({name,description,status,statusHint,icon,hint,onOpen,openLabel,pinned,onPin,pinLabel,busy,attributes}:{name:string;description:string;status:string;statusHint?:string;icon?:ReactNode;hint?:string;onOpen:()=>void;openLabel:string;pinned?:boolean;onPin?:()=>void;pinLabel?:string;busy?:boolean;attributes?:Record<string,string>}){
 return <article className={s.capabilityRow} {...attributes}><button className={s.capabilityOpen} aria-label={openLabel} onClick={onOpen}>{icon??<span className={glyph.icon}><ManagementIcon kind="file"/></span>}<span className={s.capabilityIdentity}><strong>{name}</strong><small>{description}</small>{hint&&<small className={s.draftHint}>{hint}</small>}</span><span className={s.capabilityStatus} title={statusHint}>{status}</span><span aria-hidden="true">›</span></button>{onPin&&<button className={`${s.iconButton} ${pinned?s.pinned:''}`} disabled={busy} aria-label={pinLabel} title={pinned?'取消收藏':'收藏'} aria-pressed={!!pinned} onClick={onPin}><ManagementIcon kind="pin"/></button>}</article>
}
